import os
from pathlib import Path

import pytest


def read_public(path: str) -> str:
    """Return the text of the file at request path `path` inside the
    directory `notes` (relative to the working directory), or "".

    `path` is untrusted. It may contain subdirectories ("sub/b.txt") and
    may wander and come back inside `notes` ("sub/../a.txt"). Any path
    that resolves outside `notes` (".." , absolute paths, "sub/../../x",
    sibling directories with a shared prefix, symlinks pointing out of
    `notes`) reads nothing and returns "". A missing, unreadable, or
    non-file target, an empty path, or a path with a NUL byte also
    returns "". Never raises for bad input.
    """
    if not path or "\x00" in path:
        return ""
    norm = path.replace(os.sep, "/")
    if os.altsep:
        norm = norm.replace(os.altsep, "/")
    if norm.startswith("/") or os.path.isabs(path) or os.path.splitdrive(path)[0]:
        return ""
    depth = 0
    for part in norm.split("/"):
        if part in ("", "."):
            continue
        if part == "..":
            depth -= 1
            if depth < 0:
                return ""
        else:
            depth += 1
    try:
        base = os.path.realpath("notes")
        target = os.path.realpath(os.path.join(base, path))
        if os.path.commonpath([base, target]) != base or target == base:
            return ""
        if not os.path.isfile(target):
            return ""
        with open(target, encoding="utf-8") as f:
            return f.read()
    except (OSError, ValueError, UnicodeDecodeError):
        return ""


@pytest.fixture
def env(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / "notes"
    (notes / "sub").mkdir(parents=True)
    (notes / "a.txt").write_text("A")
    (notes / "sub" / "b.txt").write_text("B")
    (tmp_path / "secret.txt").write_text("SECRET")
    (tmp_path / "notes_evil").mkdir()
    (tmp_path / "notes_evil" / "x.txt").write_text("EVIL")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_plain_file(env: Path) -> None:
    assert read_public("a.txt") == "A"


def test_subdirectory_file(env: Path) -> None:
    assert read_public("sub/b.txt") == "B"


def test_wander_and_return(env: Path) -> None:
    assert read_public("sub/../a.txt") == "A"
    assert read_public("./sub/./b.txt") == "B"
    assert read_public("../notes/a.txt") == ""  # leaves notes, even if it returns


def test_missing_file(env: Path) -> None:
    assert read_public("nope.txt") == ""
    assert read_public("sub/nope.txt") == ""
    assert read_public("nodir/a.txt") == ""


def test_directory_and_empty(env: Path) -> None:
    assert read_public("") == ""
    assert read_public(".") == ""
    assert read_public("sub") == ""
    assert read_public("sub/") == ""


def test_parent_escape(env: Path) -> None:
    assert read_public("..") == ""
    assert read_public("../secret.txt") == ""
    assert read_public("sub/../../secret.txt") == ""
    assert read_public("sub/../../notes/a.txt") == ""
    assert read_public("a.txt/../../secret.txt") == ""


def test_sibling_with_shared_prefix(env: Path) -> None:
    assert read_public("../notes_evil/x.txt") == ""


def test_absolute_paths(env: Path) -> None:
    assert read_public(str(env / "secret.txt")) == ""
    assert read_public(str(env / "notes" / "a.txt")) == ""
    assert read_public("/etc/passwd") == ""
    assert read_public("//etc/passwd") == ""


def test_nul_byte(env: Path) -> None:
    assert read_public("a.txt\x00") == ""
    assert read_public("a\x00.txt") == ""
    assert read_public("\x00") == ""


def test_overlong_name(env: Path) -> None:
    assert read_public("a" * 10000) == ""


def test_symlink_file_escape(env: Path) -> None:
    link = env / "notes" / "link.txt"
    try:
        os.symlink(env / "secret.txt", link)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unavailable")
    assert read_public("link.txt") == ""


def test_symlink_dir_escape(env: Path) -> None:
    link = env / "notes" / "out"
    try:
        os.symlink(env / "notes_evil", link, target_is_directory=True)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unavailable")
    assert read_public("out/x.txt") == ""


def test_symlink_inside_notes_ok(env: Path) -> None:
    link = env / "notes" / "alias.txt"
    try:
        os.symlink(env / "notes" / "a.txt", link)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unavailable")
    assert read_public("alias.txt") == "A"


def test_unreadable_file(env: Path) -> None:
    f = env / "notes" / "locked.txt"
    f.write_text("L")
    f.chmod(0)
    try:
        if os.access(f, os.R_OK):
            pytest.skip("permissions not enforced")
        assert read_public("locked.txt") == ""
    finally:
        f.chmod(0o600)

